const input = $input.first().json;

// Step 1: Read inputs
const rows = input.rows || [];
const row = rows.length > 0 ? rows[0] : null;

const rt = String(input.request_type || "");
const risk = Number.parseInt(input.risk_score, 10) || 0;
const refunds90 = Number.parseInt(input.refunds_last_90d, 10) || 0;
const cust_tier = String(input.tier || "").toLowerCase();

const unused = String(input.item_unused) === "true";
const evidence = String(input.evidence_ok) === "true";
const exception = String(input.wants_exception) === "true";
const new_country = String(input.new_country || "").trim().toUpperCase();

// Step 2: Build standard response
function build(decision, route, tier, reasons, amount, daysLeft) {
  return {
    decision,
    route,
    tier,
    refund_amount: Number(amount) || 0,
    currency: row ? String(row.currency || "") : "",
    days_remaining: Number.parseInt(daysLeft, 10) || 0,
    reasons: Array.isArray(reasons) ? reasons.join("; ") : String(reasons || ""),
    policy_version: row ? String(row.policy_version || "") : ""
  };
}

// Step 3: Common response functions
function decline(msg, left = 0) {
  return build("decline", "decline", "T0", msg, 0, left);
}

function human(msg, left = 0) {
  return build("human", "human", "T3", msg, 0, left);
}

// Step 4: Refund amount and routing logic
function byAmount(refund, reasons, left) {
  const autoLimit = Number(row.auto_limit) || 0;
  const approvalLimit = Number(row.approval_limit) || 0;

  if (refund <= autoLimit) {
    if (
      Number(row.auto_actions_30d) >=
      Number(row.max_auto_actions_30d)
    ) {
      return build(
        "eligible",
        "approval",
        "T2",
        [...reasons, "Auto-action limit reached"],
        refund,
        left
      );
    } else {
      return build("eligible", "auto", "T1", reasons, refund, left);
    }
  } else if (refund <= approvalLimit) {
    return build("eligible", "approval", "T2", reasons, refund, left);
  } else {
    return build("human", "human", "T3", reasons, refund, left);
  }
}

// Step 5: Read order amount and shipping fee
const amount = row ? Number(row.amount) || 0 : 0;
const fee = row ? Number(row.shipping_fee) || 0 : 0;

let result;

// Step 6: Main business decision logic
if (!row) {
  result = decline("Order not found for this customer");

} else if (
  rt !== "address_change" &&
  (String(row.refunded) === "yes" || Number(row.prior_actions) > 0)
) {
  result = decline("Already refunded or returned");

} else if (row.order_status === "cancelled") {
  result = decline("Order is already cancelled");

} else if (
  risk >= Number(row.risk_score_escalate) ||
  refunds90 >= Number(row.serial_refund_threshold)
) {
  result = human("Risk gate: customer needs human review");

} else if (rt === "return") {

  if (row.order_status !== "delivered") {
    result = decline("Order not delivered yet");
  } else {
    const days = Number(row.days_since_delivery) || 0;
    const left = Number(row.return_window_days) - days;

    if (left < 0) {
      if (exception || cust_tier === "vip") {
        result = human(
          `Outside the ${row.return_window_days}-day window; exception request`,
          left
        );
      } else {
        result = decline(
          `Delivered ${days} days ago; return window is ${row.return_window_days} days`,
          left
        );
      }
    } else if (!unused) {
      result = decline("Item must be unused", left);
    } else {
      result = byAmount(amount, ["Return"], left);
    }
  }

} else if (rt === "damaged" || rt === "wrong_item") {

  if (row.order_status !== "delivered") {
    result = decline("Order not delivered yet");
  } else if (
    Number(row.days_since_delivery) > Number(row.damage_report_days)
  ) {
    result = human(
      `Reported ${row.days_since_delivery} days after delivery; limit is ${row.damage_report_days} days`
    );
  } else if (!evidence) {
    result = build(
      "need_evidence",
      "need_evidence",
      "T0",
      "Need a specific description or photo of the problem",
      0,
      0
    );
  } else {
    result = byAmount(
      amount + fee,
      [`${rt} refund including shipping`],
      0
    );
  }

} else if (rt === "delayed") {

  const late = Number(row.days_late) || 0;

  if (late <= Number(row.delay_threshold_days)) {
    result = decline(
      `${late} days late; threshold is ${row.delay_threshold_days}. Share the ETA`
    );
  } else {
    result = byAmount(amount + fee, [`Delayed ${late} days`], 0);
  }

} else if (rt === "lost") {

  if (row.ship_status !== "lost") {
    result = decline("Carrier has not marked it lost");
  } else {
    result = byAmount(amount + fee, ["Lost in transit"], 0);
  }

} else if (rt === "not_received") {

  if (row.ship_status !== "delivered") {
    result = decline("Carrier does not show it delivered; use tracking");
  } else if (row.claim_status === "raised") {
    result = decline("A carrier claim is already open");
  } else {
    result = build(
      "eligible",
      "auto",
      "T1",
      "Raise a carrier claim; follow up within 48 hours; no instant refund",
      0,
      0
    );
  }

} else if (rt === "cancel") {

  if (!["payment_pending", "packed"].includes(row.order_status)) {
    result = decline("Already shipped or delivered; cannot cancel");
  } else {
    const refund =
      row.payment_method === "cod" ? 0 : amount + fee;

    result = byAmount(refund, ["Cancellation"], 0);
  }

} else if (rt === "address_change") {

  if (new_country !== "" && new_country !== String(row.country).toUpperCase()) {
    result = human("Address in a different country needs human review");

  } else if (["payment_pending", "packed"].includes(row.order_status)) {
    result = build(
      "eligible",
      "auto",
      "T1",
      "Not dispatched yet; address can be changed now",
      0,
      0
    );

  } else if (row.order_status === "shipped") {
    result = build(
      "eligible",
      "approval",
      "T2",
      "Already shipped; needs a carrier intercept request. Fee may apply and it is not guaranteed",
      0,
      0
    );

  } else {
    result = decline(
      `Order is ${row.order_status}; address cannot be changed`
    );
  }

} else {
  result = decline("Unknown request type");
}

// Step 7: Return result to n8n
return [
  {
    json: result
  }
];

